import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

// Create axios instance with auth header
const api = axios.create({
  baseURL: "http://localhost:8000",
});

// Add interceptor to include token in requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

function OCRSpaceBillUpload() {
  const navigate = useNavigate();
  const [selectedFile, setSelectedFile] = useState(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState(null);
  const [message, setMessage] = useState("");
  const [profile, setProfile] = useState(null);
  const [dragActive, setDragActive] = useState(false);

  // Check authentication on component mount
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      navigate("/login");
      return;
    }
    
    fetchProfile();
    testOCRSpace();
  }, [navigate]);

  const fetchProfile = async () => {
    try {
      const res = await api.get("/profile");
      setProfile(res.data);
    } catch (err) {
      console.error("Error fetching profile:", err);
      if (err.response?.status === 401) {
        localStorage.removeItem("token");
        navigate("/login");
      }
    }
  };

  const testGoogleVision = async () => {
    try {
      const res = await api.get("/bills/test-google-vision");
      if (res.data.status === "error") {
        showMessage(res.data.message, true);
      }
    } catch (err) {
      console.error("Error testing Google Vision:", err);
    }
  };

  const showMessage = (msg, isError = false) => {
    setMessage(msg);
    setTimeout(() => setMessage(""), isError ? 7000 : 5000);
  };

  const handleFileSelect = (event) => {
    const file = event.target.files[0];
    validateAndSetFile(file);
  };

  const validateAndSetFile = (file) => {
    if (!file) return;

    // Check file type
    const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/bmp', 'image/tiff', 'image/gif', 'application/pdf'];
    if (!allowedTypes.includes(file.type)) {
      showMessage("Please select a valid image file (JPG, PNG, BMP, TIFF, GIF) or PDF.", true);
      return;
    }

    // Check file size (max 10MB)
    const maxSize = 10 * 1024 * 1024; // 10MB
    if (file.size > maxSize) {
      showMessage("File size must be less than 10MB.", true);
      return;
    }

    setSelectedFile(file);
    setResult(null); // Clear previous results
    setMessage("");
  };

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      validateAndSetFile(e.dataTransfer.files[0]);
    }
  };

  const uploadBill = async () => {
    if (!selectedFile) {
      showMessage("Please select a file first.", true);
      return;
    }

    setIsProcessing(true);
    setMessage("");

    try {
      const formData = new FormData();
      formData.append("file", selectedFile);

      const response = await api.post("/bills/upload-bill", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
        timeout: 60000, // 60 second timeout
      });

      const data = response.data;

      if (data.status === "success") {
        setResult(data);
        showMessage(data.message || "Bill uploaded and processed successfully!");
      } else {
        showMessage(data.error || "Failed to process the bill.", true);
        setResult(data); // Still show partial results
      }
    } catch (err) {
      console.error("Bill upload error:", err);
      if (err.response?.status === 401) {
        localStorage.removeItem("token");
        navigate("/login");
      } else if (err.code === 'ECONNABORTED') {
        showMessage("Processing timeout. Please try with a smaller file or better quality image.", true);
      } else {
        showMessage(err.response?.data?.detail || "Error processing bill. Please try again.", true);
      }
      setResult(null);
    } finally {
      setIsProcessing(false);
    }
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return "Not detected";
    try {
      const date = new Date(dateStr);
      return date.toLocaleDateString();
    } catch {
      return dateStr;
    }
  };

  const formatAmount = (amount) => {
    if (amount === null || amount === undefined) return "Not detected";
    return `$${parseFloat(amount).toFixed(2)}`;
  };

  return (
    <div className="bill-upload-container">
      <div className="bill-upload-header">
        <h1>🔍 Google Vision Bill Upload</h1>
        <p>Upload your bill and let Google Vision API extract the information automatically</p>
        {profile && (
          <div className="user-info">
            <span>Welcome, {profile.full_name || profile.username}!</span>
          </div>
        )}
      </div>

      {message && (
        <div className={`message ${message.includes("Error") || message.includes("Failed") ? "error" : "success"}`}>
          {message}
        </div>
      )}

      <div className="bill-upload-section">
        <h2>📄 Upload Bill</h2>
        
        <div
          className={`file-drop-zone ${dragActive ? "drag-active" : ""}`}
          onDragEnter={handleDrag}
          onDragLeave={handleDrag}
          onDragOver={handleDrag}
          onDrop={handleDrop}
        >
          <div className="drop-zone-content">
            <div className="upload-icon">📁</div>
            <p>Drag and drop your bill here, or</p>
            <label className="file-input-label">
              <input
                type="file"
                accept="image/*,application/pdf"
                onChange={handleFileSelect}
                className="file-input"
              />
              Choose File
            </label>
          </div>
        </div>

        {selectedFile && (
          <div className="selected-file">
            <p><strong>Selected:</strong> {selectedFile.name} ({(selectedFile.size / 1024 / 1024).toFixed(2)} MB)</p>
          </div>
        )}

        <button
          onClick={uploadBill}
          disabled={!selectedFile || isProcessing}
          className="process-btn"
        >
          {isProcessing ? "🔄 Processing..." : "🚀 Upload & Process Bill"}
        </button>
      </div>

      {result && (
        <div className="bill-results-section">
          <h2>📊 Extracted Bill Information</h2>
          
          <div className="results-grid">
            <div className="result-card">
              <h3>👤 Employee</h3>
              <p>{result.employee_name || "Not detected"}</p>
            </div>
            
            <div className="result-card">
              <h3>🏷️ Bill Type</h3>
              <p className={`bill-type ${result.bill_type}`}>
                {result.bill_type ? result.bill_type.charAt(0).toUpperCase() + result.bill_type.slice(1) : "Not detected"}
              </p>
            </div>
            
            <div className="result-card">
              <h3>🏪 Vendor</h3>
              <p>{result.vendor || "Not detected"}</p>
            </div>
            
            <div className="result-card">
              <h3>📅 Date</h3>
              <p>{formatDate(result.date)}</p>
            </div>
            
            <div className="result-card">
              <h3>💰 Amount</h3>
              <p className="amount">{formatAmount(result.amount)}</p>
            </div>
            
            {result.bill_id && (
              <div className="result-card">
                <h3>🆔 Bill ID</h3>
                <p>#{result.bill_id}</p>
              </div>
            )}
          </div>

          {result.processing_time && (
            <div className="processing-info">
              <p><strong>Processing Time:</strong> {result.processing_time.toFixed(2)}s</p>
            </div>
          )}

          {result.raw_text && (
            <div className="raw-text-section">
              <h3>📝 Raw OCR Text</h3>
              <div className="raw-text-container">
                <pre>{result.raw_text}</pre>
              </div>
            </div>
          )}
        </div>
      )}

      <div className="instructions">
        <h3>📋 Instructions</h3>
        <ul>
          <li>Upload clear, high-quality images of your bills</li>
          <li>Supported formats: JPG, PNG, BMP, TIFF, GIF, PDF</li>
          <li>Maximum file size: 10MB</li>
          <li>Google Vision API will extract text and parse bill information</li>
          <li>Extracted data is automatically stored in the database</li>
        </ul>
      </div>
    </div>
  );
}

export default GoogleVisionBillUpload;
